begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('00000000-0000-0000-0000-000000000191','delete-owner@example.invalid','{"requested_username":"DeleteOwner"}'),
 ('00000000-0000-0000-0000-000000000192','delete-voter@example.invalid','{"requested_username":"DeleteVoter"}');
insert into auth.sessions(id,user_id) values ('50000000-0000-0000-0000-000000000191','00000000-0000-0000-0000-000000000191');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000191","role":"authenticated","session_id":"50000000-0000-0000-0000-000000000191"}',true);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000191',0,'Public survivor','','food-drink','donut','public','{"mode":"per-round","roundMinutes":[60]}',array['One','Two']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000192',0,'Private manual','','food-drink','donut','private','{"mode":"manual"}',array['One','Two']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000193',0,'Private timed','','food-drink','donut','private','{"mode":"per-round","roundMinutes":[60]}',array['One','Two']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000194',0,'Private finished','','food-drink','donut','private','{"mode":"manual"}',array['One','Two']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000195',0,'Public finished','','food-drink','donut','public','{"mode":"per-round","roundMinutes":[60]}',array['One','Two']);
select public.submit_bracket(id,1) from public.brackets where owner_id='00000000-0000-0000-0000-000000000191';
update app_private.bracket_review_queue set not_before=clock_timestamp()-interval '1 second';
select app_private.process_competitions();
select public.close_manual_round('10000000-0000-0000-0000-000000000194',0);
alter table public.bracket_rounds disable trigger guard_round_structure;
update public.bracket_rounds set starts_at=starts_at-interval '2 hours',ends_at=ends_at-interval '2 hours' where bracket_id='10000000-0000-0000-0000-000000000195';
alter table public.bracket_rounds enable trigger guard_round_structure;
select app_private.process_competitions();
select public.save_bracket_draft('10000000-0000-0000-0000-000000000196',0,'Public pending','','food-drink','donut','public','{"mode":"per-round","roundMinutes":[60]}',array['One','Two']);
select public.submit_bracket('10000000-0000-0000-0000-000000000196',1);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000197',0,'Public draft','','food-drink','donut','public','{"mode":"per-round","roundMinutes":[60]}',array['One','Two']);
create temp table deletion_match as select id,left_entry_id from public.bracket_matchups where bracket_id='10000000-0000-0000-0000-000000000191';
select public.cast_bracket_vote((select id from deletion_match),(select left_entry_id from deletion_match),0,gen_random_uuid());
select public.save_competition('10000000-0000-0000-0000-000000000191',true);
insert into public.bracket_memberships(bracket_id,user_id) values ('10000000-0000-0000-0000-000000000192','00000000-0000-0000-0000-000000000192');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000192","role":"authenticated"}',true);
select public.save_competition('10000000-0000-0000-0000-000000000192',true);
select public.save_competition('10000000-0000-0000-0000-000000000191',true);
select throws_ok($$select public.delete_account()$$,'42501',null,'deletion requires a live session');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000191","role":"authenticated","session_id":"50000000-0000-0000-0000-000000000191"}',true);
select lives_ok($$select public.delete_account()$$,'owner deletes their identity atomically');
select is((select count(*) from auth.users where id='00000000-0000-0000-0000-000000000191'),0::bigint,'auth identity is gone');
select is((select count(*) from auth.sessions where user_id='00000000-0000-0000-0000-000000000191'),0::bigint,'sessions are revoked');
select is((select count(*) from public.profiles where id='00000000-0000-0000-0000-000000000191'),0::bigint,'profile and username removed');
select is((select count(*) from public.saved_brackets where user_id='00000000-0000-0000-0000-000000000191'),0::bigint,'personal saved list removed');
select is((select count(*) from public.brackets),2::bigint,'only started public brackets survive');
select ok((select bool_and(owner_id is null) from public.brackets),'surviving ownership anonymized');
select is((select count(*) from public.bracket_entries where bracket_id in ('10000000-0000-0000-0000-000000000192','10000000-0000-0000-0000-000000000193','10000000-0000-0000-0000-000000000194')),0::bigint,'all private competitors removed');
select is((select count(*) from app_private.bracket_review_queue),0::bigint,'pending activation cancelled');
select is((select count(*) from app_private.bracket_ballots where voter_id is null),1::bigint,'already cast ballot kept without identity');
select throws_ok($$select public.save_competition('10000000-0000-0000-0000-000000000191',true)$$,'42501',null,'deleted JWT cannot mutate');
select throws_ok($$select public.delete_account()$$,'42501',null,'deleted session cannot repeat deletion');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000192","role":"authenticated"}',true);
select is((select count(*) from public.saved_brackets where bracket_id is null),1::bigint,'private saved link becomes unavailable marker');
select is((select count(*) from public.saved_brackets where bracket_id='10000000-0000-0000-0000-000000000191'),1::bigint,'public saved link stays valid');
select throws_ok($$select public.delete_competition('10000000-0000-0000-0000-000000000191')$$,'42501',null,'outsider cannot delete anonymous bracket');
select throws_ok($$select public.close_manual_round('10000000-0000-0000-0000-000000000191',0)$$,'42501',null,'outsider cannot control anonymous bracket');
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000191',1)$$,'42501',null,'outsider cannot submit anonymous bracket');
select throws_ok($$update public.brackets set owner_id='00000000-0000-0000-0000-000000000192' where id='10000000-0000-0000-0000-000000000191'$$,'55000',null,'anonymous brackets cannot be claimed');
select ok(not has_function_privilege('authenticated','public.deactivate_account()','execute'),'deactivation API retired');
select ok(not has_function_privilege('authenticated','public.reactivate_account()','execute'),'reactivation API retired');
select ok(not has_function_privilege('anon','public.delete_account()','execute'),'anonymous visitors cannot delete accounts');
select set_config('request.jwt.claims','{}',true);
select is(public.get_competition('10000000-0000-0000-0000-000000000191')->>'creator',null::text,'public snapshot no longer includes username');
alter table public.bracket_rounds disable trigger guard_round_structure;
update public.bracket_rounds set starts_at=starts_at-interval '2 hours',ends_at=ends_at-interval '2 hours' where bracket_id='10000000-0000-0000-0000-000000000191';
alter table public.bracket_rounds enable trigger guard_round_structure;
select app_private.process_competitions();
select is((select status from public.brackets where id='10000000-0000-0000-0000-000000000191'),'completed','anonymous timed bracket finishes normally');
select is((select left_votes from public.bracket_match_results where matchup_id=(select id from deletion_match)),1::bigint,'anonymous ballot counts in results');
select is((select count(*) from app_private.bracket_ballots),0::bigint,'anonymous ballot purged after finalization');
select is((select count(*) from app_private.deleting_accounts),0::bigint,'no deletion markers left behind');
select * from finish();
rollback;
